"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Calendar } from "@/components/ui/calendar"
import { useFieldControl } from "@/components/ui/field"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"

type DatePickerProps = Omit<React.ComponentProps<"button">, "value" | "defaultValue" | "onChange" | "type"> & {
  value?: Date
  defaultValue?: Date
  onValueChange?: (date: Date | undefined) => void
  /** The words before the date: "Deliver the brief by". Clicking them opens the month. */
  label?: string
  /** What the line says before a day is chosen. */
  placeholder?: string
  /** Days before today can't be chosen. */
  disablePast?: boolean
  locale?: string
  /** Classes for the sentence around the date. className goes to the button. */
  rootClassName?: string
  /** Pins a state for documentation ("hover", "focus"); set on the button. */
  "data-force"?: string
}

/** "Thursday, 1 October": the date as words. */
function words(date: Date, locale: string) {
  let previous = ""
  return new Intl.DateTimeFormat(locale, { weekday: "long", day: "numeric", month: "long" })
    .formatToParts(date)
    .map((part) => {
      const out = part.type === "literal" && previous === "weekday" && !part.value.includes(",") ? ", " : part.value
      previous = part.type
      return out
    })
    .join("")
}

/**
 * A date inside a sentence, like the select. It opens the month on a leader line;
 * choose a day and it is written into the sentence in italic. Works alone or inside a Field.
 */
function DatePicker({
  value: valueProp,
  defaultValue,
  onValueChange,
  label,
  placeholder = "choose a day",
  disablePast,
  locale = "en-GB",
  className,
  rootClassName,
  ...props
}: DatePickerProps) {
  const field = useFieldControl()
  const [open, setOpen] = React.useState(false)
  const [own, setOwn] = React.useState(defaultValue)
  const value = valueProp ?? own
  const id = props.id ?? field.id
  const Root = label ? "label" : "span"

  const pick = (date: Date) => {
    if (valueProp === undefined) setOwn(date)
    onValueChange?.(date)
    setOpen(false)
  }

  // A Field's label names the button, which hides the button's own words; say the date as a description too.
  const spoken = field.id && value ? `${field.id}-date` : undefined

  return (
    <Root data-slot="date-picker" className={cn("db-date-root", rootClassName)}>
      {label ? <span>{label}</span> : null}
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <button
            type="button"
            data-slot="date-picker-trigger"
            data-set={value ? "" : undefined}
            className={cn("db-date", className)}
            {...props}
            id={id}
            data-invalid={field["aria-invalid"] ? "" : undefined}
            aria-describedby={[props["aria-describedby"] ?? field["aria-describedby"], spoken].filter(Boolean).join(" ") || undefined}
          >
            {value ? words(value, locale) : placeholder}
          </button>
        </PopoverTrigger>
        <PopoverContent data-slot="date-picker-content" className="db-date-pop" aria-label={label ?? "Choose a day"}>
          <Calendar value={value} disablePast={disablePast} locale={locale} onValueChange={pick} />
        </PopoverContent>
      </Popover>
      {spoken ? (
        <span id={spoken} className="db-sr">
          {words(value!, locale)}
        </span>
      ) : null}
    </Root>
  )
}

export { DatePicker, type DatePickerProps }

@layer components {
  /* ── db-date ── a date inside a sentence, like the select. The month hangs from it
     on a leader line (a db-pop holding a Calendar); the chosen day is written in italic. */
  .db-date-root { display: inline-flex; flex-wrap: wrap; align-items: baseline; column-gap: 0.4em; font-size: var(--db-mp); line-height: var(--db-mp-lh); color: var(--db-graphite); }
  .db-field > .db-date-root { grid-column: 1 / -1; justify-self: start; }
  .db-date {
    appearance: none; border: 0; border-radius: 0; margin: 0; padding: 0 0 0.1em; cursor: pointer;
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline);
    color: var(--db-pencil); font: inherit; line-height: 1.2;
    transition: background-color var(--db-allegro);
  }
  :is(.db-date:hover, .db-date[data-force~="hover"]) { background-image: linear-gradient(var(--db-ink), var(--db-ink)); }
  .db-date[data-set] { color: var(--db-ink); font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); }
  .db-date[data-invalid] { background-image: linear-gradient(var(--db-signal), var(--db-signal)); }
  .db-date:disabled { color: var(--db-pencil); cursor: not-allowed; background-image: none; }
  .db-date-pop > .db-month { width: min(21rem, 78vw); gap: var(--db-space-5); }
  .db-date-pop .db-month-date { font-size: var(--db-f); }
  .db-date-pop .db-month-grid { gap: var(--db-space-2); }
  .db-date-pop .db-month-day { font-size: var(--db-pp); }
}
